#pragma once\n\n#include <glm/glm.hpp>\n#include <cstdint>\n\nnamespace sclpr::collision {\n\nenum class SensorType : std::uint8_t {\n    Floor,\n    Wall,\n    Ceiling,\n    Water\n};\n\nstruct SensorState {\n    bool isActive{false};\n    glm::vec2 position{0.0f, 0.0f};\n    glm::vec2 contactPoint{0.0f, 0.0f};\n    float contactAngle{0.0f};\n    float contactDistance{0.0f};\n};\n\nstruct SensorResult {\n    bool colliding{false};\n    glm::vec2 contactPoint{0.0f, 0.0f};\n    float contactAngle{0.0f};\n    float contactDistance{0.0f};\n    std::uint32_t tileType{0};\n};\n\nclass Sensor {\npublic:\n    explicit Sensor(SensorType type, glm::vec2 offset = glm::vec2(0.0f, 0.0f));\n    ~Sensor() = default;\n\n    void SetOffset(const glm::vec2& offset) noexcept;\n    void SetWorldPosition(const glm::vec2& parentPos) noexcept;\n    void Update(float dt) noexcept;\n    void RegisterCollision(const SensorResult& result) noexcept;\n    void ClearCollision() noexcept;\n\n    SensorType GetType() const noexcept;\n    const glm::vec2& GetOffset() const noexcept;\n    const glm::vec2& GetWorldPosition() const noexcept;\n    const SensorState& GetState() const noexcept;\n    bool IsColliding() const noexcept;\n\nprivate:\n    SensorType m_type;\n    glm::vec2 m_offset;\n    glm::vec2 m_worldPosition;\n    SensorState m_state;\n};\n\n} // namespace sclpr::collision\n